function shape(data, input) {
function shape(rows) {
  const byPlan = new Map();
  for (const r of rows) {
    if (!byPlan.has(r.plan)) byPlan.set(r.plan, []);
    byPlan.get(r.plan).push({ name: r.name });
  }
  return [...byPlan].map(([plan, accounts]) => ({ plan, accounts }));
}
return shape(data.rows, input);
}
